package com.lexorion.payroll.repository;
import com.lexorion.payroll.domain.PayRunEmployee;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface PayRunEmployeeRepository extends JpaRepository<PayRunEmployee,UUID>{List<PayRunEmployee>findByPayRunIdOrderByEmployeeCodeAsc(UUID payRunId);boolean existsByPayRunIdAndPayrollEmployeeId(UUID payRunId,UUID employeeId);long countByPayRunId(UUID payRunId);@Query("select distinct e from PayRunEmployee e join fetch e.payRun r join fetch e.calculation c left join fetch c.lines where r.workspace.id=:workspaceId and e.employeeCode=:employeeCode and r.status=com.lexorion.payroll.domain.PayRunStatus.FINALIZED order by r.periodEnd desc,r.payRunKey desc")List<PayRunEmployee>findFinalizedPayslips(@Param("workspaceId")UUID workspaceId,@Param("employeeCode")String employeeCode);@Query("select distinct e from PayRunEmployee e join fetch e.payRun r join fetch e.calculation c left join fetch c.lines where r.workspace.id=:workspaceId and e.employeeCode=:employeeCode and r.payRunKey=:payRunKey and r.status=com.lexorion.payroll.domain.PayRunStatus.FINALIZED")Optional<PayRunEmployee>findFinalizedPayslip(@Param("workspaceId")UUID workspaceId,@Param("employeeCode")String employeeCode,@Param("payRunKey")String payRunKey);
 @Query("select count(e) from PayRunEmployee e join e.payRun r where r.workspace.id=:workspaceId and e.employeeCode=:employeeCode and r.id<>:runId and r.status in (com.lexorion.payroll.domain.PayRunStatus.CALCULATED,com.lexorion.payroll.domain.PayRunStatus.FINALIZED) and r.periodStart<=:periodEnd and r.periodEnd>=:periodStart")
 long countCommittedOverlap(@Param("workspaceId") UUID workspaceId, @Param("employeeCode") String employeeCode, @Param("runId") UUID runId, @Param("periodStart") java.time.LocalDate periodStart, @Param("periodEnd") java.time.LocalDate periodEnd);

 @Query("select count(e) from PayRunEmployee e join e.payRun r join e.calculation c join c.lines l where r.workspace.id=:workspaceId and e.employeeCode=:employeeCode and r.id<>:runId and r.status in (com.lexorion.payroll.domain.PayRunStatus.CALCULATED,com.lexorion.payroll.domain.PayRunStatus.FINALIZED) and l.occurrence=com.lexorion.payroll.domain.OccurrenceType.ONE_TIME and (l.sourceAssignmentId=:assignmentId or (l.sourceAssignmentId is null and exists (select a.id from ComponentAssignment a where a.id=:assignmentId and a.componentKey=l.componentKey and a.profile.payrollEmployee.id=e.payrollEmployee.id and a.profile.effectiveFrom<=c.calculationDate and (a.profile.effectiveTo is null or a.profile.effectiveTo>=c.calculationDate))))")
 long countConsumedOneTime(@Param("workspaceId") UUID workspaceId, @Param("employeeCode") String employeeCode, @Param("runId") UUID runId, @Param("assignmentId") UUID assignmentId);
}
